# -*- coding: utf-8 -*-
# Gesundheitstipps der Naturheilpraxis. Ton: Lebensgewohnheiten und Tradition, keine Wirk- oder Heilversprechen (HWG).
T = []
def add(k, titel, kurz, text, zutaten=None, zubereitung=None):
    T.append(dict(k=k, titel=titel, kurz=kurz, text=text, zutaten=zutaten, zubereitung=zubereitung))

TEE="Tee der Jahreszeit"; AL="Alltagsgriff"; RZ="Hausmittel"; RU="Ruhe und Atem"; KN="Kneipp und Wasser"; BW="Bewegung"

add(TEE,"Ingwer-Zitronen-Tee","Wärmend und frisch: ein Klassiker für kalte Herbsttage.","Frischer Ingwer gibt dem Tee eine angenehme Schärfe, die viele an kühlen Tagen als wohltuend empfinden. Der Tee eignet sich als warmes Getränk zwischendurch. Wer empfindlich auf Schärfe reagiert, nimmt weniger Ingwer.",["3 cm frischer Ingwer","1 Bio-Zitrone","500 ml heißes Wasser","nach Geschmack Honig"],"Ingwer in dünne Scheiben schneiden, mit heißem Wasser übergießen und 10 Minuten ziehen lassen. Zitronensaft und nach Belieben Honig erst in die leicht abgekühlte Tasse geben.")
add(TEE,"Fencheltee am Abend","Ein ruhiger Abschluss des Tages.","Fenchel wird in der Volksheilkunde seit Langem als milder Abendtee geschätzt. Er schmeckt leicht süßlich und passt gut als feste Gewohnheit vor dem Schlafengehen, etwa nach dem Abendessen.",["1 TL Fenchelsamen","250 ml heißes Wasser"],"Die Samen kurz im Mörser leicht anquetschen, mit heißem Wasser übergießen, zugedeckt 10 Minuten ziehen lassen und abseihen.")
add(TEE,"Salbeitee mit Zitrone","Herb-würzig und traditionell beliebt in der kühlen Jahreszeit.","Salbei hat einen kräftig-würzigen Geschmack und wird seit Jahrhunderten als Tee getrunken. Wegen des starken Aromas genügt eine kleine Menge. In Schwangerschaft und Stillzeit sowie bei Medikamenteneinnahme bitte vorher Rücksprache halten.",["4 bis 5 frische Salbeiblätter oder 1 TL getrockneter Salbei","250 ml heißes Wasser","etwas Zitronensaft"],"Salbei mit heißem Wasser übergießen, 5 bis 8 Minuten ziehen lassen, abseihen und mit Zitrone abschmecken.")
add(TEE,"Thymiantee","Aromatisch und warm, mit Honig besonders mild.","Thymian ist ein bekanntes Küchenkraut und liefert einen aromatischen, leicht herben Tee. Er passt gut zu nasskalten Tagen und lässt sich mit etwas Honig abrunden.",["1 TL getrockneter Thymian oder 2 frische Zweige","250 ml heißes Wasser","etwas Honig"],"Thymian mit heißem Wasser übergießen, 8 bis 10 Minuten zugedeckt ziehen lassen, abseihen und süßen.")
add(TEE,"Lindenblütentee","Ein sanfter, blumiger Wärmespender.","Lindenblütentee schmeckt mild und leicht süßlich. Er wird traditionell gern an kühlen Abenden getrunken, wenn man sich eine Auszeit mit einer warmen Tasse gönnen möchte.",["1 bis 2 TL Lindenblüten","250 ml heißes Wasser"],"Blüten mit heißem Wasser übergießen, 10 Minuten zugedeckt ziehen lassen und abseihen.")
add(TEE,"Hagebuttentee","Fruchtig-herb, ein kräftiger Herbstgeschmack.","Hagebutten sind die Früchte der Heckenrose und wachsen im Herbst an vielen Wegrändern. Der Tee hat eine fruchtig-säuerliche Note und färbt sich rötlich. Getrocknete Früchte gibt es im Handel.",["2 TL getrocknete Hagebutten","250 ml Wasser"],"Hagebutten leicht zerstoßen, mit kochendem Wasser übergießen und 10 bis 15 Minuten ziehen lassen, dann abseihen.")
add(TEE,"Kamillentee","Mild und vertraut, ein Tee für ruhige Minuten.","Kamille ist einer der bekanntesten Kräutertees. Er schmeckt mild und leicht blumig und begleitet viele Menschen durch ruhige Abende. Wer auf Korbblütler allergisch reagiert, sollte vorsichtig sein.",["1 EL Kamillenblüten","250 ml heißes Wasser"],"Blüten mit heißem Wasser übergießen, zugedeckt 5 bis 10 Minuten ziehen lassen und abseihen.")
add(TEE,"Zimt-Apfel-Tee","Der Duft von Herbst und Weihnachtszeit.","Getrocknete Apfelstücke und eine Zimtstange ergeben einen Tee, der schon beim Aufgießen nach Herbst duftet. Zimt bitte in Maßen verwenden, Zimtstangen sind dabei meist die bessere Wahl als gemahlenes Pulver.",["1 Handvoll getrocknete Apfelstücke","1 Zimtstange","500 ml heißes Wasser"],"Äpfel und Zimtstange mit heißem Wasser übergießen, 10 Minuten ziehen lassen und abseihen.")
add(TEE,"Holunderbeerensaft heiß","Warm, dunkel und fruchtig.","Holunderbeeren dürfen nicht roh gegessen werden, sondern müssen erhitzt werden. Als Saft schmeckt er heiß verdünnt wie ein fruchtiger Wintertee. Fertigen Saft gibt es im Reformhaus.",["100 ml Holunderbeersaft (gekauft oder selbst gekocht)","150 ml heißes Wasser","etwas Honig"],"Saft mit heißem Wasser mischen und nach Belieben mit Honig süßen.")
add(TEE,"Pfefferminztee zwischendurch","Frisch und klar, auch ohne Zucker lecker.","Pfefferminze bringt ein frisches, kühles Aroma in die Tasse. Der Tee passt zu jeder Tageszeit und lässt sich gut aus frischen Blättern vom Balkon aufgießen.",["1 Handvoll frische Pfefferminzblätter oder 1 TL getrocknete","250 ml heißes Wasser"],"Blätter mit heißem Wasser übergießen, 5 Minuten ziehen lassen und abseihen.")
add(TEE,"Brennnesseltee","Herb und grün, ein einfacher Kräutertee.","Brennnesseln gelten als typisches Wildkraut. Der Tee schmeckt herb-grün und wird in der Pflanzenheilkunde traditionell gern als Frühjahrs- oder Herbstkur genutzt. Wie bei jedem Kraut gilt: gute Qualität kaufen, in kleinen Mengen beginnen.",["1 bis 2 TL getrocknete Brennnesselblätter","250 ml heißes Wasser"],"Blätter mit heißem Wasser übergießen, 10 Minuten ziehen lassen und abseihen.")
add(TEE,"Gewürztee mit Kardamom und Nelke","Ein duftender Wintertee für Genießer.","Kardamom, Nelke und Zimt ergeben eine Würzmischung, die an Chai erinnert. Sie schmeckt besonders mit etwas Milch oder Hafermilch. Wegen der Intensität genügt eine kleine Menge Gewürze.",["2 Kardamomkapseln","1 Nelke","1 Zimtstange","1 Scheibe Ingwer","250 ml Wasser"],"Gewürze leicht anquetschen, mit Wasser 5 Minuten leise kochen lassen, abseihen und nach Geschmack mit Milch verfeinern.")
add(TEE,"Lavendeltee zum Abschalten","Zart und blumig, mit nur wenigen Blüten.","Lavendel duftet intensiv. Für den Tee reicht deshalb eine kleine Menge, sonst schmeckt er seifig. Getrunken wird er traditionell zum Abendritual.",["1 TL Lavendelblüten (Lebensmittelqualität)","250 ml heißes Wasser"],"Blüten mit heißem Wasser übergießen, 5 Minuten ziehen lassen und abseihen.")

add(AL,"Das Glas Wasser am Morgen","Ein kleiner Anfang für den Tag.","Ein Glas Wasser nach dem Aufstehen ist eine einfache Gewohnheit. Viele nutzen sie, um bewusst in den Tag zu starten. Zimmerwarm ist für Empfindliche oft angenehmer als eiskalt.")
add(AL,"Warmes Fußbad am Abend","Wärme für Füße und Gedanken.","Ein warmes Fußbad ist ein bewährtes Hausmittel für kühle Abende. Der Wärmereiz ist für viele angenehm und lädt zum Abschalten ein. Das Wasser beginnt bei etwa 36 °C und darf auf 38 bis 40 °C ansteigen. Bei Durchblutungsstörungen oder Diabetes bitte vorher Rücksprache halten.",["Wanne mit Wasser","1 Handvoll Meersalz (optional)"],"15 bis 20 Minuten baden, danach abtrocknen und warme Socken anziehen.")
add(AL,"Kneipp: der kalte Armguss","Kurz, klar und belebend.","Ein kalter Armguss ist eine bekannte Kneipp-Anwendung. Dabei läuft kaltes Wasser kurz über die Arme. Viele erleben das als erfrischenden Start in den Tag. Bei Herz-Kreislauf-Beschwerden bitte zuvor ärztlichen Rat einholen.",None,"Kaltes Wasser vom Handgelenk aus langsam bis zur Schulter laufen lassen, etwa 20 bis 30 Sekunden, dann sanft abstreifen und warm anziehen.")
add(AL,"Spaziergang im Tageslicht","Draußen sein, auch bei grauem Wetter.","Im Herbst und Winter bekommen wir weniger Tageslicht. Ein halbstündiger Spaziergang am Vormittag bringt Bewegung und Licht, auch bei bewölktem Himmel. Der Himmel ist draußen auch dann heller als im Zimmer.")
add(AL,"Rhythmus statt Perfektion","Regelmäßig essen, schlafen, bewegen.","Der Körper mag Rhythmus. Feste Zeiten für Mahlzeiten und Schlaf geben vielen ein Gefühl von Halt. Das muss nicht streng sein, schon eine ungefähre Regelmäßigkeit ist eine gute Grundlage für einen geordneten Tag.")
add(AL,"Bewusst frühstücken","Zehn Minuten ohne Bildschirm.","Ein Frühstück ohne Handy und Nachrichten schafft einen ruhigen Beginn. Wer sich zehn Minuten Zeit nimmt, nimmt auch Hunger und Sättigung besser wahr.")
add(AL,"Die Wechseldusche","Warm und kalt im Wechsel, nach Kneipp.","Wechselduschen sind eine bekannte Kneipp-Anwendung. Dabei wird warmes und kaltes Wasser abwechselnd angewendet. Sie gelten als belebender Reiz. Bei Herz-Kreislauf-Erkrankungen bitte nur nach Rücksprache.",None,"Erst warm duschen, dann kurz kalt von den Füßen aufwärts abbrausen, abtrocknen und warm anziehen. Mit wenigen Sekunden Kälte beginnen.")
add(AL,"Stoßlüften statt Dauerkipp","Frische Luft in der Heizperiode.","Im Winter ist die Raumluft oft trocken. Mehrmals täglich ein paar Minuten die Fenster ganz öffnen bringt frische Luft in die Räume, ohne sie auszukühlen. Das Schlafzimmer darf ruhig kühler sein.")
add(AL,"Bewegung in kleinen Portionen","Fünf Minuten zählen schon.","Wer viel sitzt, kann stündlich kurz aufstehen, sich strecken, ein Glas Wasser holen und ein paar Schritte gehen. Solche kleinen Pausen summieren sich und lockern Schultern und Rücken.")
add(AL,"Barfuß auf dem Boden","Füße spüren lassen.","Barfuß zu Hause zu gehen, ist eine einfache Möglichkeit, die Füße zu beanspruchen und die Haut wahrzunehmen. Bei Kälte tragen wir natürlich Hausschuhe oder warme Socken.")
add(AL,"Der Tag mit einem Dank","Eine Minute am Abend.","Am Abend kurz überlegen, was gut gelaufen ist, ist ein einfaches Ritual. Viele empfinden das als gelassen machend und schließen den Tag damit ruhiger ab.")

add(RU,"Atmen: vier ein, sechs aus","Eine einfache Übung für zwischendurch.","Eine bekannte Atemübung ist die längere Ausatmung: durch die Nase vier Sekunden einatmen, durch den Mund sechs Sekunden ausatmen. Fünf Wiederholungen reichen. Viele empfinden das als beruhigend. Bei Schwindel die Übung abbrechen.")
add(RU,"Eine Minute Stille","Nichts tun, nur da sein.","Eine Minute still zu sitzen, ohne Handy und ohne Aufgabe, ist eine kleine Pause für den Kopf. Man kann dabei auf den Atem achten oder auf die Geräusche im Raum.")
add(RU,"Der Abendspaziergang","Den Tag draußen ausklingen lassen.","Ein kurzer Spaziergang nach dem Abendessen gehört in vielen Kulturen zum Tagesablauf. Er bringt Bewegung, frische Luft und einen Abstand zum Alltag.")
add(RU,"Handy aus, Licht gedämpft","Eine halbe Stunde vor dem Schlafen.","Wer vor dem Schlafen Bildschirme meidet und das Licht dämpft, gibt dem Abend einen ruhigeren Ablauf. Statt Nachrichten kann ein Buch oder eine Tasse Tee den Tag beschließen.")
add(RU,"Schlafzimmer kühl und dunkel","Gute Bedingungen für die Nacht.","Viele schlafen in einem kühlen, dunklen und leisen Zimmer besser. Etwa 16 bis 18 °C gelten als angenehm. Ein Lüften vor dem Schlafengehen gehört dazu.")
add(RU,"Dehnen am Morgen","Fünf Minuten für den Rücken.","Nach dem Aufstehen ein paar Minuten die Arme nach oben strecken, die Schultern kreisen und den Rücken sanft dehnen. Das kann sich lockernd anfühlen und ist ein einfacher Start in den Tag.")

add(RZ,"Zwiebelsirup nach Großmutters Art","Ein altes Hausrezept.","Zwiebelsirup ist ein traditionelles Hausmittel aus zwei Zutaten. Er wird in vielen Familien seit Generationen zubereitet. Für Menschen mit empfindlichem Magen ist er vielleicht nicht das Richtige.",["1 große Zwiebel","3 EL Honig oder Zucker"],"Zwiebel würfeln, mit Honig vermengen, einige Stunden zugedeckt stehen lassen und den entstandenen Saft abseihen.")
add(TEE,"Goldene Milch","Warm, cremig und gewürzt.","Goldene Milch ist ein Getränk aus Milch oder Pflanzenmilch mit Kurkuma und Ingwer. Sie ist beliebt als warmer Abendbegleiter. Kurkuma färbt stark, bitte nicht auf helle Textilien kleckern.",["250 ml Milch oder Hafermilch","1 TL Kurkuma","1 Scheibe Ingwer","1 Prise Pfeffer","etwas Honig"],"Alles erwärmen, nicht kochen, 5 Minuten ziehen lassen, abseihen und mit Honig abschmecken.")

add(KN,"Wassertreten","Kühles Wasser, kurze Dauer, warme Füße danach.","Wassertreten gehört zu den bekanntesten Kneipp-Anwendungen: Man steht in kniehohem kaltem Wasser und hebt abwechselnd die Beine wie ein Storch. Viele erleben das als erfrischend. Wichtig ist, dass die Füße vorher warm sind und danach wieder gut gewärmt werden. Bei Blasenreizung, Durchblutungsstörungen oder Herz-Kreislauf-Beschwerden bitte vorher Rücksprache halten.",None,"Badewanne oder Eimer mit kaltem Wasser bis zu den Knien füllen, 30 bis 60 Sekunden storchenartig gehen, Wasser abstreifen, warme Socken anziehen und sich bewegen.")
add(KN,"Der Knieguss","Ein kurzer Wasserstrahl, ein belebender Reiz.","Der Knieguss ist ein klassischer Kneipp-Guss. Kaltes Wasser läuft von den Füßen aufwärts bis zum Knie. Viele beschreiben ihn als erfrischenden Beginn oder Abschluss des Tages. Mit wenigen Sekunden beginnen und nur mit warmen Füßen anwenden.",None,"Wasserstrahl ohne Druck am rechten Fuß von außen beginnen, an der Außenseite bis zum Knie hinaufführen und an der Innenseite zurück. Dann links wiederholen, Wasser abstreifen und warm anziehen.")
add(BW,"Schultern lösen","Eine Minute für Nacken und Schultern.","Wer viel sitzt, kennt verspannte Schultern. Mehrmals am Tag die Schultern langsam nach hinten kreisen, die Arme locker hängen lassen und dabei ruhig atmen. Das kann sich wohltuend anfühlen und kostet kaum Zeit.")
add(BW,"Der Igelball unter dem Fuß","Die Fußsohle spüren und rollen.","Mit einem kleinen Igel- oder Tennisball unter dem Fuß lässt sich die Fußsohle sanft massieren. Man rollt den Ball langsam von der Ferse bis zum Ballen. Viele finden das angenehm, besonders nach langem Stehen. Bei Schmerzen die Übung abbrechen.")
add(BW,"Zehn Schritte mit Aufmerksamkeit","Langsam gehen und den Boden spüren.","Eine einfache Übung im Alltag: zehn Schritte ganz langsam gehen und auf den Kontakt der Füße mit dem Boden achten. Sie lässt sich im Flur oder im Garten üben und macht den Kopf frei.")
add(RZ,"Orangenschalen als Raumduft","Ein natürlicher Duft für kalte Tage.","Frische Orangenschalen mit ein paar Nelken auf der warmen Heizung oder in einer Schale verbreiten einen angenehmen Duft. Der Duft von Zitrusfrüchten wird von vielen als frisch und heiter empfunden. Auf Bio-Qualität achten.",["Schalen von 2 Bio-Orangen","3 bis 4 Nelken","1 Zimtstange (optional)"],"Schalen mit Nelken und Zimt in eine Schale legen und auf einen warmen Platz stellen.")
add(RU,"Das Summen am Abend","Eine Minute summen, ruhig ausatmen.","Beim Ausatmen einen tiefen, gleichmäßigen Summton hervorbringen: Man spürt die Schwingung im Gesicht und im Brustkorb. Viele empfinden das als beruhigend. Drei bis fünf Atemzüge genügen. Bei Schwindel die Übung beenden.")
add(RU,"Herbst: Zeit des Loslassens","Ein Gedanke aus der Traditionellen Chinesischen Medizin.","In der Traditionellen Chinesischen Medizin gilt der Herbst als Zeit des Elements Metall. Es steht sinnbildlich für Klarheit und Loslassen, so wie Bäume die Blätter abwerfen. Ein Anlass, den Herbst bewusst zu nutzen: Altes sortieren, Überflüssiges abgeben, früh nach Hause gehen und die Abende ruhiger gestalten.")
